coding.solution:
from itertools import product

def review_table(names, table):
    missing, conflicts = [], []
    for combo in product([True, False], repeat=len(names)):
        case = dict(zip(names, combo))
        actions = {action for conds, action in table
                   if all(v == '-' or case[k] == v for k, v in conds.items())}
        if not actions:
            missing.append(combo)
        elif len(actions) > 1:
            conflicts.append(combo)
    return {'missing': sorted(missing), 'conflicts': sorted(conflicts)}
